-- ── Verify ────────────────────────────────────────────────────────────────────
SELECT
  COUNT(DISTINCT entity_id) AS greek_entities_total,
  COUNT(DISTINCT CASE WHEN entity_id IN (SELECT entity_id FROM entity_periods) THEN entity_id END) AS now_periodized,
  COUNT(DISTINCT CASE WHEN entity_id NOT IN (SELECT entity_id FROM entity_periods) THEN entity_id END) AS still_unperiodized
FROM entities WHERE tradition = 'Greek';

SELECT * FROM v_release_metrics;

